import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The error text recorded when every allowed attempt has failed. */
export const TRANSIENT_FAILURE = 'transient failure';

/** One row of the `jobs` table, as stored. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  /** Epoch milliseconds before which a queued job must not be picked up (retry back-off). */
  next_run_at: number;
  created_at: string;
  updated_at: string;
}

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL,
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  completed INTEGER NOT NULL DEFAULT 0,
  result_output TEXT,
  error TEXT,
  idempotency_key TEXT UNIQUE,
  next_run_at INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_status_seq ON jobs (status, seq);
CREATE TABLE IF NOT EXISTS worker_heartbeat (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  ts INTEGER NOT NULL
);
`;

/**
 * Opens the SQLite database shared by the server and worker processes and makes sure the schema
 * exists. Both processes call this, so the schema statements are idempotent.
 */
export function openDatabase(path: string = process.env.DATABASE_PATH || 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}

/** Runs `fn` inside a write transaction that takes the write lock up front. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

export function getJobById(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

export function getJobByKey(db: DatabaseSync, key: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
}

/** All jobs, newest first. */
export function listJobs(db: DatabaseSync): JobRow[] {
  return db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
}

export function insertJob(
  db: DatabaseSync,
  job: { id: string; input: string; steps: number; failAttempts: number; idempotencyKey: string | null },
): JobRow {
  const now = new Date().toISOString();
  db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, next_run_at, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
  ).run(job.id, job.input, job.steps, job.failAttempts, job.idempotencyKey, now, now);
  return getJobById(db, job.id)!;
}

/** True when the worker wrote a heartbeat within the last `windowMs` milliseconds. */
export function workerAlive(db: DatabaseSync, now: number, windowMs = 3000): boolean {
  const row = db.prepare('SELECT ts FROM worker_heartbeat WHERE id = 1').get() as { ts: number } | undefined;
  return row !== undefined && row.ts > 0 && now - row.ts < windowMs;
}

/** The public JSON shape of a job. */
export function toJob(row: JobRow) {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

