import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, transaction, TRANSIENT_FAILURE, type JobRow } from './db.ts';

/** Time per processing step. */
const STEP_MS = 100;
/** Back-off before a failed attempt is retried (within the 250 ms to 2 s allowed). */
const RETRY_DELAY_MS = 500;
/** Total attempts allowed for one job. */
const MAX_ATTEMPTS = 3;
/** How often an idle worker looks for queued work. */
const POLL_MS = 200;
const HEARTBEAT_MS = 1000;

const db = openDatabase();
const now = () => new Date().toISOString();

// Attempts that were running when a previous worker died go back into the queue.
db.prepare(`UPDATE jobs SET status = 'queued', completed = 0, next_run_at = 0, updated_at = ? WHERE status = 'running'`).run(now());

let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function heartbeat(ts: number): void {
  db.prepare(`INSERT INTO worker_heartbeat (id, ts) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET ts = excluded.ts`).run(ts);
}

/** Atomically takes the oldest due queued job and marks it running for a new attempt. */
function claimNextJob(): JobRow | undefined {
  return transaction(db, () => {
    const row = db
      .prepare(`SELECT * FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq LIMIT 1`)
      .get(Date.now()) as unknown as JobRow | undefined;
    if (!row) return undefined;
    db.prepare(`UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE seq = ?`).run(now(), row.seq);
    return { ...row, status: 'running', attempts: row.attempts + 1, completed: 0 };
  });
}

/** Puts an interrupted attempt back in the queue; it is picked up again later. */
function requeueInterrupted(job: JobRow): void {
  db.prepare(`UPDATE jobs SET status = 'queued', completed = 0, next_run_at = 0, updated_at = ? WHERE seq = ?`).run(now(), job.seq);
}

function failAttempt(job: JobRow): void {
  if (job.attempts < MAX_ATTEMPTS) {
    db.prepare(`UPDATE jobs SET status = 'queued', completed = 0, next_run_at = ?, updated_at = ? WHERE seq = ?`).run(
      Date.now() + RETRY_DELAY_MS,
      now(),
      job.seq,
    );
  } else {
    db.prepare(`UPDATE jobs SET status = 'failed', completed = 0, result_output = NULL, error = ?, updated_at = ? WHERE seq = ?`).run(
      TRANSIENT_FAILURE,
      now(),
      job.seq,
    );
  }
}

function completeJob(job: JobRow): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE seq = ?`,
  ).run(job.input.toUpperCase(), now(), job.seq);
}

/** Runs one attempt of a job. The attempt number is `job.attempts`, already incremented. */
async function runAttempt(job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    // Simulated transient failure: fails at the first step, before any progress.
    await sleep(STEP_MS);
    if (stopping) return requeueInterrupted(job);
    return failAttempt(job);
  }
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return requeueInterrupted(job);
    db.prepare(`UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ?`).run(step, now(), job.seq);
  }
  completeJob(job);
}

heartbeat(Date.now());
const heartbeatTimer = setInterval(() => heartbeat(Date.now()), HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  const job = claimNextJob();
  if (!job) {
    await sleep(POLL_MS);
    continue;
  }
  await runAttempt(job);
}

clearInterval(heartbeatTimer);
heartbeat(0);
db.close();
console.log('worker stopped');

