21	<body>
22	  <h1>Job tracker</h1>
23	
24	  <form data-testid="job-form" novalidate>
25	    <label>Input
26	      <input data-testid="job-input" name="input" type="text" autocomplete="off">
27	    </label>
28	    <label>Steps
29	      <input data-testid="job-steps" name="steps" type="text" inputmode="numeric" value="5">
30	    </label>
31	    <label>Fail attempts
32	      <input data-testid="job-fail-attempts" name="failAttempts" type="text" inputmode="numeric" value="0">
33	    </label>
34	    <button data-testid="job-submit" type="submit">Submit job</button>
35	  </form>
36	
37	  <div data-testid="form-error" role="alert"></div>
38	
39	  <h2>Jobs</h2>
40	  <ul data-testid="job-list"></ul>
41	
42	  <script>
43	    const form = document.querySelector('[data-testid="job-form"]');
44	    const inputField = document.querySelector('[data-testid="job-input"]');
45	    const stepsField = document.querySelector('[data-testid="job-steps"]');
46	    const failField = document.querySelector('[data-testid="job-fail-attempts"]');
47	    const submitButton = document.querySelector('[data-testid="job-submit"]');
48	    const formError = document.querySelector('[data-testid="form-error"]');
49	    const list = document.querySelector('[data-testid="job-list"]');
50	
51	    // Numeric text is sent as a number; anything else is sent as typed so the API's validation applies.
52	    function numberOrText(raw) {
53	      const s = raw.trim();
54	      const n = Number(s);
55	      return s !== '' && Number.isFinite(n) ? n : raw;
56	    }
57	
58	    function describeError(data, status) {
59	      const err = data && data.error;
60	      if (!err) return `Request failed (${status}).`;
61	      let text = err.message || err.code || 'Request failed.';
62	      if (Array.isArray(err.fields) && err.fields.length > 0) {
63	        text += ' ' + err.fields.map((f) => `${f.field}: ${f.message}`).join('; ');
64	      }
65	      return text;
66	    }
67	
68	    form.addEventListener('submit', async (event) => {
69	      event.preventDefault();
70	      formError.textContent = '';
71	      submitButton.disabled = true;
72	      try {
73	        const res = await fetch('/api/jobs', {
74	          method: 'POST',
75	          headers: { 'content-type': 'application/json' },
76	          body: JSON.stringify({
77	            input: inputField.value,
78	            steps: numberOrText(stepsField.value),
79	            failAttempts: numberOrText(failField.value),
80	          }),
81	        });
82	        const data = await res.json().catch(() => null);
83	        if (res.ok) {
84	          inputField.value = '';
85	          await refresh();
86	        } else {
87	          formError.textContent = describeError(data, res.status);
88	        }
89	      } catch {
90	        formError.textContent = 'Could not reach the server.';
91	      } finally {
92	        submitButton.disabled = false;
93	      }
94	    });
95	
96	    function jobItem(job) {
97	      const li = document.createElement('li');
98	      li.setAttribute('data-testid', 'job-item');
99	      li.dataset.jobId = job.id;
100	
101	      const input = document.createElement('div');
102	      input.className = 'job-input';
103	      input.textContent = job.input;
104	
105	      const meta = document.createElement('div');
106	      meta.className = 'job-meta';
107	      const status = document.createElement('span');
108	      status.setAttribute('data-testid', 'job-status');
109	      status.textContent = job.status;
110	      const progress = document.createElement('span');
111	      progress.setAttribute('data-testid', 'job-progress');
112	      progress.textContent = `${job.progress.completed}/${job.progress.total}`;
113	      meta.append(status, ' · ', progress, ` · attempts ${job.attempts}`);
114	
115	      const result = document.createElement('div');
116	      result.setAttribute('data-testid', 'job-result');
117	      if (job.status === 'completed' && job.result) result.textContent = job.result.output;
118	      else if (job.status === 'failed' && job.error) result.textContent = job.error;
119	      else result.textContent = '';
120	
121	      const id = document.createElement('div');
122	      id.className = 'job-id';
123	      id.textContent = job.id;
124	
125	      li.append(input, meta, result, id);
126	      return li;
127	    }
128	
129	    async function refresh() {
130	      try {
131	        const res = await fetch('/api/jobs', { cache: 'no-store' });
132	        if (!res.ok) return;
133	        const body = await res.json();
134	        list.replaceChildren(...body.jobs.map(jobItem));
135	      } catch {
136	        // Server unreachable; keep the last list and try again on the next tick.
137	      }
138	    }
139	
140	    refresh();
141	    setInterval(refresh, 1000);
142	  </script>
